namespace HunterGuild
{
    /// <summary>DIHASILKAN dari dokumen "Ashwatch Lore". Isi teks = lore asli; ubah di sini bila lore direvisi.</summary>
    public static partial class LoreDB
    {
        static LoreEntry[] Build()
        {
            return new[]
            {
                new LoreEntry("prolog", "Hunter Baru di Gerbang Ashwatch", "Prolog", 1, new[] {
                    "Retakan itu tidur lebih lama dari yang siapa pun kira. Empat wadah Lucifer tetap diam, tersembunyi, menunggu.\n\nSampai sekarang.\n\nSampai seorang hunter baru — yang belum tahu apa-apa tentang Sang Perintis, tentang Tujuh Dewa, tentang Dark Mana yang mengalir diam-diam di bawah tanah yang dipijaknya — berjalan melewati gerbang Ashwatch untuk pertama kalinya, membawa hanya satu hal: keinginan untuk memulai sebagai hunter Rank G.\n\nDia tidak tahu bahwa langkah pertamanya hari itu adalah bab pertama dari sesuatu yang jauh lebih besar dari sekadar memburu monster untuk bertahan hidup.",
                }),
                new LoreEntry("sang_perintis", "Sang Perintis", "Sejarah Guild", 1, new[] {
                    "Guild Petualang di Ashwatch sudah berdiri jauh sebelum kebenaran tentang hutan itu terungkap — awalnya hanya perkumpulan sederhana para pemburu dan petualang yang mencari nafkah dari hasil hutan, tidak berbeda dengan guild-guild sejenis di kota lain. Tidak ada yang istimewa dari mereka, sampai satu orang bergabung.",
                    "Dia bukan siapa-siapa. Bukan keturunan bangsawan, bukan mantan prajurit kekaisaran, bukan pula seseorang dengan latar belakang yang layak diceritakan turun-temurun — hanya seorang rakyat biasa yang bergabung dengan Guild karena alasan paling sederhana: butuh cara untuk bertahan hidup. Namanya sendiri lambat laun hilang dari catatan sejarah Ashwatch, tenggelam oleh gelar yang lebih diingat orang: Sang Perintis.\n\nYang membuatnya berbeda dari hunter lain bukan kekuatan atau keberanian semata, melainkan sesuatu yang lebih halus: dia bertahan hidup dari pertarungan-pertarungan yang seharusnya menghancurkan mental siapa pun.",
                }),
                new LoreEntry("kutukan_hutan", "Kutukan yang Diterima Begitu Saja", "Sejarah Guild", 1, new[] {
                    "Kutukan yang Diterima Begitu Saja\n\nSebelum kebenaran terungkap, para pemburu Guild yang terlalu sering bertarung dekat bagian terdalam hutan biasanya pulang membawa mimpi buruk, bisikan aneh di kepala, atau bahkan kehilangan akal perlahan-lahan. Ini dianggap wajar — semacam “kutukan hutan” yang diterima begitu saja sebagai risiko pekerjaan. Sang Perintis tidak pernah mengalaminya, meski dia yang paling sering mengambil misi paling berbahaya di antara semua orang di Guild.",
                    "Rasa penasaran itulah yang membawanya menjelajah lebih dalam dari siapa pun sebelumnya, sampai dia menemukan reruntuhan kuil tua tersembunyi di jantung hutan — jauh lebih tua dari sejarah kekaisaran mana pun, dengan ukiran yang nyaris hancur dimakan waktu. Sebagai orang biasa yang bahkan mungkin tidak sepenuhnya bisa membaca aksara kuno dengan lancar, dia butuh waktu lama untuk memahami sebagian dari apa yang tertulis di sana — kisah tentang Tujuh Dewa Muasal, tentang satu yang jatuh, dan tentang warisan cahaya yang dititipkan diam-diam ke dalam darah sebagian manusia.",
                    "Dia mulai menyadari: bukan kebetulan dia selalu pulang dengan jernih sementara yang lain tidak. Sesuatu di dalam dirinya menolak kegelapan yang coba menempel setiap kali dia bertarung.",
                }),
                new LoreEntry("asal_rank", "Asal Mula Sistem Rank", "Sejarah Guild", 1, new[] {
                    "Sang Perintis, setelah memahami ini, mengusulkan cara baru merekrut dan menguji hunter di Guild — bukan sekadar siapa yang berani, tapi siapa yang benar-benar bisa bertahan menghadapi Dark Mana tanpa termakan olehnya, persis seperti dirinya. Metode pengujiannya sederhana namun efektif: calon hunter dihadapkan pada monster terlemah lebih dulu — bukan untuk menguji kekuatan, melainkan menguji apakah mereka pulang dengan pikiran tetap jernih. Yang bertahan, direkrut. Yang mulai menunjukkan tanda-tanda termakan kegelapan, diminta berhenti demi keselamatan mereka sendiri.\n\nAsal Mula Sistem Rank dan Afinitas",
                    "Inilah asal mula sistem Rank — bukan diciptakan oleh cendekiawan istana atau ahli strategi kerajaan, melainkan oleh seorang rakyat biasa yang belajar lewat pengalamannya sendiri, dan ingin memastikan tidak ada hunter lain yang harus kehilangan akal seperti yang nyaris terjadi pada rekan-rekannya. Rank G, pada awalnya, bukan berarti “misi termudah” — melainkan “jarak teraman”, cara Guild memastikan Hunter baru tidak langsung dihadapkan pada kegelapan yang terlalu pekat sebelum diketahui seberapa kuat mereka bisa bertahan.",
                }),
                new LoreEntry("cahaya_enam", "Warisan Cahaya Enam Dewa", "Rahasia Guild", 2, new[] {
                    "Kenapa Hunter Muncul\n\nDi kuil itu tertulis — samar, nyaris hilang dimakan waktu — bahwa keenam dewa di Surga, jauh sebelum Lucifer jatuh sepenuhnya ke dalam kebenciannya, sempat menitipkan sedikit dari cahaya mereka sendiri ke dalam garis keturunan manusia tertentu. Bukan sebagai kekuatan yang mencolok atau berkah yang disadari pemiliknya, melainkan sesuatu yang tidur diam di dalam darah — sebuah bentuk perlindungan kecil yang diwariskan turun-temurun, tanpa pernah benar-benar dipahami tujuannya, karena saat dititipkan, Dark Mana bahkan belum ada untuk dilawan.",
                    "Manusia-manusia dengan warisan itulah yang kelak menjadi Hunter pertama. Bukan karena mereka lebih kuat secara fisik, bukan karena latihan yang lebih keras — tapi karena sesuatu di dalam diri mereka secara alami menolak Dark Mana yang mencoba menempel, membiarkan mereka bertarung melawan monster tanpa membawa pulang kegelapan yang sama.",
                }),
                new LoreEntry("guild_master", "Rahasia Para Guild Master", "Rahasia Guild", 2, new[] {
                    "Sang Perintis sendiri tidak pernah menjabat posisi resmi yang mewah — dia tetap seorang hunter biasa sampai akhir hayatnya, hanya diakui secara tidak resmi sebagai orang yang paling dipercaya di Guild. Barulah generasi setelahnya yang mengangkat posisi itu menjadi gelar formal: Guild Master, diwariskan turun-temurun bukan lewat garis keturunan darah, melainkan lewat kepercayaan — Guild Master lama memilih penerus yang dianggap paling layak melanjutkan rahasia dan tanggung jawab yang sama.",
                    "Rahasia itu — tentang Tujuh Dewa, tentang Lucifer, tentang Dark Mana yang mengalir diam-diam di bawah hutan Ashwatch — diwariskan hanya dari satu Guild Master ke Guild Master berikutnya, tidak pernah disebarkan ke seluruh kota. Sementara itu, warisan cahaya dalam diri sebagian keturunan manusia — yang membuat Sang Perintis dan hunter-hunter terpilih lainnya bisa bertahan dari Dark Mana — perlahan dikenal dengan nama yang lebih sederhana oleh Guild modern: Afinitas. Sisa terakhir dari cahaya enam dewa, yang tidak pernah benar-benar padam, meski pemiliknya sendiri tidak pernah tahu dari mana asalnya.",
                }),
                new LoreEntry("tujuh_dewa", "Tujuh Dewa Muasal", "Dunia Purba", 2, new[] {
                    "Sebelum ada manusia. Sebelum ada nama untuk tanah, laut, atau langit. Yang ada hanyalah Tujuh — tujuh entitas muasal yang lahir dari kekosongan, dan dari tangan merekalah dunia ini pertama kali dibentuk.\n\nEnam dari mereka menciptakan bersama. Enam dari mereka membangun Surga sebagai singgasana, tempat mereka memerintah berdampingan, saling berbagi cahaya yang sama.\n\nYang ketujuh tidak.",
                    "Namanya Lucifer — yang paling muda, yang paling bersinar di antara mereka semua sebelum kejatuhannya, dan justru karena itulah dia dijauhkan. Sejarah yang dituturkan generasi ke generasi berbeda-beda ceritanya: sebagian bilang dia dihukum karena menolak tunduk. Sebagian bilang dia dikorbankan agar keenam saudaranya bisa hidup damai tanpa perlu berbagi kekuasaan dengannya. Dan sebagian lagi — yang paling jarang diceritakan, karena paling menyakitkan untuk dipercaya — mengatakan dia sendiri yang memilih pergi, karena tak sanggup melihat dirinya perlahan dilupakan di tengah keramaian saudara-saudaranya.",
                    "Apa pun kebenarannya, satu hal yang pasti: Lucifer diturunkan ke Neraka, sementara enam saudaranya tetap bersinar di Surga.\n\nSendirian. Selamanya.",
                }),
                new LoreEntry("dark_mana", "Dark Mana", "Dunia Purba", 2, new[] {
                    "Kebencian yang dipendam Lucifer bukan sekadar perasaan. Di tangan seorang dewa muasal, bahkan emosi punya bobot — dan cemburu yang mengeras selama ribuan tahun itu perlahan berubah menjadi sesuatu yang nyata: sebuah esensi gelap yang mengalir dari dirinya sendiri, mengendap di setiap sudut Neraka, dan pada akhirnya meluap.\n\nManusia yang jauh di kemudian hari mempelajarinya lewat sihir akan menyebutnya Dark Mana — energi purba yang tidak diciptakan dari kehidupan, melainkan dari ketiadaannya. Bukan cahaya yang gelap, tapi kekosongan yang diberi bentuk oleh amarah.",
                    "Neraka tidak bisa menampungnya selamanya. Dark Mana yang terus menerus lahir dari kesendirian Lucifer akhirnya mencari jalan keluar — merembes lewat retakan-retakan tertua di antara dunia, titik-titik lemah yang sudah ada sejak awal penciptaan, sisa dari saat batas antara Neraka dan benua manusia pertama kali digambar. Salah satu retakan itu — yang paling dalam, yang paling tua — kelak akan dikenal manusia sebagai tanah tempat berdirinya Ashwatch.",
                    "Ketika Dark Mana menyentuh dunia manusia, ia tidak diam. Ia tidak seperti sihir biasa yang menunggu dirapal. Ia mencari kehidupan untuk ditumpangi — sesuatu untuk diberi bentuk, diberi nafas, diberi kehendak untuk merusak sebagai perpanjangan dari kehendak Lucifer sendiri.",
                }),
                new LoreEntry("kelahiran_monster", "Kelahiran Monster", "Dunia Purba", 2, new[] {
                    "Hewan-hewan hutan biasa adalah yang pertama tersentuh. Serigala yang terlalu lama tinggal dekat retakan mulai berubah — bulunya menghitam, matanya menyala merah pudar, dan sesuatu di dalam dirinya yang dulu liar tapi wajar kini berubah menjadi ganas tanpa alasan, seolah hewan itu sendiri ketakutan pada apa yang tumbuh di dalam tubuhnya. Goblin-goblin kecil yang dulu hanya pengganggu desa kini muncul dalam jumlah yang tak wajar, seolah digandakan oleh sesuatu yang tak terlihat.",
                    "Inilah kelahiran monster: bukan spesies yang diciptakan, melainkan makhluk yang dijangkiti. Setiap monster yang diburu hunter Ashwatch — dari yang paling lemah di Rank G sampai yang paling kuat — membawa jejak Dark Mana yang sama, hanya berbeda seberapa dalam ia sudah meresap.\n\nNamun Dark Mana yang menyebar liar seperti itu tidak efisien di mata Lucifer. Terlalu acak, terlalu lemah, terlalu mudah dibasmi satu per satu oleh manusia yang justru semakin terlatih membunuh mereka — ironi yang tidak luput dari perhatian Lucifer. Hunter-hunter kecil itu, tanpa mereka sadari, sedang menempa diri mereka sendiri menjadi ancaman yang lebih besar untuknya di masa depan.",
                }),
                new LoreEntry("cemburu", "Cemburu yang Membatu", "Dunia Purba", 3, new[] {
                    "Dari singgasananya yang gelap, Lucifer menyaksikan. Dia menyaksikan saudara-saudaranya menciptakan manusia — makhluk kecil, rapuh, penuh cacat, namun dicintai tanpa syarat, dijaga, diberkati. Dia menyaksikan doa-doa manusia naik ke langit, disambut enam pasang tangan yang hangat. Dia menyaksikan dunia yang indah itu tumbuh subur di bawah naungan cahaya yang bukan miliknya.\n\nDan setiap malam yang tak pernah berakhir di Neraka, satu pertanyaan yang sama terus membakar dalam dirinya:\n\n“Kenapa aku yang harus sendiri, sementara mereka punya segalanya?”",
                    "Cemburu yang dipendam terlalu lama tidak pernah tetap diam. Ia membusuk. Ia berubah bentuk. Dan pada akhirnya, cemburu Lucifer mengeras menjadi sesuatu yang jauh lebih dingin — kebencian yang sabar.\n\nDia tahu dia tidak bisa menyerang Surga secara langsung — hukum kosmis yang mengikat ketujuh dewa muasal melarang itu, hukum yang bahkan dia sendiri ikut menyusunnya dulu, di masa ketika mereka masih bersaudara. Tapi hukum itu tidak melindungi ciptaan mereka.\n\nManusia adalah kebanggaan enam saudaranya. Manusia adalah bukti cinta yang tidak pernah diberikan padanya.\n\nMaka manusialah yang akan dia hancurkan.",
                }),
                new LoreEntry("empat_luka", "Empat Luka Lucifer", "Dunia Purba", 3, new[] {
                    "Bukan dengan pasukan. Bukan dengan perang terbuka — itu terlalu cepat, terlalu jujur, dan terlalu mudah dilawan. Lucifer memilih cara yang jauh lebih sabar, jauh lebih kejam: dia akan membiarkan celah-celah kecil di antara dunia tetap terbuka, mengirim bagian dari dirinya sedikit demi sedikit ke benua manusia — lewat monster, lewat makhluk buas, lewat empat entitas yang paling setia padanya, yang kelak akan dikenal manusia sebagai momok paling ditakuti dalam sejarah mereka.\n\nSang Naga, yang membawa amukan dan api.\n\nCerberus, sang penjaga gerbang yang tak kenal ampun.\n\nBehemoth, yang berjalan dan meratakan apa pun yang menghalanginya.\n\nSang Demon, bayangan Lucifer sendiri yang paling menyerupainya.",
                    "Mereka bukan sekadar monster. Mereka adalah luka yang sengaja dibiarkan terbuka. Peringatan. Ancaman. Dan — jika dibiarkan cukup lama — jalan.",
                }),
                new LoreEntry("ashwatch_jaga", "Yang Sebenarnya Dijaga Ashwatch", "Rahasia Guild", 3, new[] {
                    "Ribuan tahun berlalu. Kekaisaran manusia lahir, tumbuh, terpecah menjadi belasan kerajaan. Sejarah tentang tujuh dewa muasal memudar menjadi dongeng anak-anak, menjadi ukiran usang di dinding kuil tua. Manusia lupa bahwa kejatuhan Lucifer bukan akhir dari cerita — hanya jeda.\n\nDan di satu titik kecil di ujung dunia, di mana hutan bertemu dengan celah tertua di antara dua dunia, sebuah pos kecil berdiri untuk menjaga luka lama itu tetap tertutup.\n\nManusia menyebutnya Ashwatch.\n\nMereka mengira mereka menjaga perbatasan.\n\nYang sebenarnya mereka jaga adalah kesabaran seorang dewa yang telah menunggu ribuan tahun untuk didengar.",
                }),
                new LoreEntry("distrik", "Distrik Bangsawan dan Rahasia yang Terputus", "Rahasia Guild", 3, new[] {
                    "Dan Distrik Bangsawan, yang baru dibangun jauh setelah masa Sang Perintis ketika Ashwatch mulai berkembang jadi kota sungguhan, tidak pernah mewarisi rahasia itu sama sekali. Setiap Gubernur yang ditunjuk dari luar hanya melihat Guild sebagai “organisasi pemburu lokal” — berguna, tapi tidak istimewa. Kesenjangan pengetahuan inilah yang, ribuan tahun kemudian, menjadi akar dari konflik antara Guild dan Gubernur di masa pemain bermain.",
                }),
                new LoreEntry("wadah_naga", "Wadah Pertama: Sang Naga", "Empat Wadah", 3, new[] {
                    "Maka Lucifer memilih jalan yang lebih sabar dan lebih personal. Alih-alih membiarkan Dark Mana menyebar buta, ia memusatkan sebagian besar esensi dirinya ke dalam empat wadah yang cukup kuat untuk menampungnya tanpa hancur — empat makhluk yang bukan sekadar terjangkit, melainkan ditempa langsung dari kehendaknya:\n\nIa mengambil seekor reptil purba yang hampir punah di celah gunung berapi, dan menuangkan amarahnya ke dalam darahnya — lahirlah Sang Naga, bukan sekadar kadal raksasa bernapas api, melainkan murka Lucifer yang diberi sisik dan sayap.",
                }),
                new LoreEntry("wadah_cerberus", "Wadah Kedua: Cerberus", "Empat Wadah", 3, new[] {
                    "Ia mengambil seekor anjing penjaga kuil tua yang lama ditinggalkan, dan menggandakan kepalanya, menggandakan tekadnya untuk tidak pernah membiarkan siapa pun lewat — lahirlah Cerberus, penjaga yang setia bukan pada tuan yang hidup, tapi pada dendam yang mati-matian ingin dijaga tetap membara.",
                }),
                new LoreEntry("wadah_behemoth", "Wadah Ketiga: Behemoth", "Empat Wadah", 3, new[] {
                    "Ia mengambil seekor banteng liar yang mengamuk di padang tak berpenghuni, dan menanamkan berat dari seluruh kesepiannya ke dalam setiap langkahnya — lahirlah Behemoth, yang berjalan bukan untuk sampai ke suatu tempat, melainkan untuk meratakan segala yang mengingatkannya bahwa dunia ini terus berjalan tanpa dirinya.",
                }),
                new LoreEntry("wadah_demon", "Wadah Keempat: Sang Demon", "Empat Wadah", 3, new[] {
                    "Dan yang terakhir, ia tidak mengambil dari makhluk lain sama sekali. Ia mengambil dari dirinya sendiri — memisahkan sebagian dari jiwanya yang paling gelap, paling murni berisi kebencian tanpa filter apa pun — dan membentuknya menjadi wujud yang paling menyerupai dirinya. Manusia yang kelak bertemu dengannya di rank tertinggi akan menyebutnya sederhana saja: Sang Demon. Karena tidak ada nama lain yang cukup untuk sesuatu yang lahir langsung dari inti seorang dewa yang jatuh.",
                }),
                new LoreEntry("kesabaran", "Kesabaran Seorang Dewa", "Dunia Purba", 4, new[] {
                    "Keempatnya dikirim bukan untuk menyerang sekaligus. Lucifer tahu kesabaran adalah senjata terbaiknya, satu-satunya hal yang ribuan tahun kesendirian ajarkan padanya dengan sempurna. Mereka ditempatkan tersebar di titik-titik yang jauh, tertidur, menunggu — hingga saatnya tiba ketika manusia di Ashwatch cukup kuat, cukup penasaran, cukup berani untuk menggali terlalu dalam ke hutan yang seharusnya mereka takuti.\n\nKarena bagi Lucifer, ini bukan sekadar tentang menghancurkan manusia.\n\nIni tentang membuktikan pada enam saudaranya di Surga — bahwa ciptaan kesayangan mereka, sekuat apa pun mereka kira, pada akhirnya akan tunduk pada kegelapan yang lahir dari kesepian yang mereka sendiri yang ciptakan untuknya.",
                }),
                new LoreEntry("hollow_circle", "Hollow Circle, Kultus Pemuja Lucifer", "Dunia Purba", 2, new[] {
                    "Hollow Circle bukan bandit dan bukan pemberontak. Mereka kultus pemuja Lucifer: orang-orang yang percaya retakan di bawah Ashwatch harus dibuka, bukan ditutup.\n\nMereka menandai diri dengan lingkaran kosong di telapak tangan, simbol wadah yang menunggu diisi Dark Mana. Para pemburu menemukan mereka di Lembah Iblis, di reruntuhan utara, dan di dungeon yang tiba-tiba 'tidak aman'.\n\nSiapa yang membiayai mereka masih menjadi pertanyaan antara Guild dan Gubernur."
                }),
            };
        }
    }
}